import os, signal, glob
for p in glob.glob('/proc/[0-9]*/cmdline'):
    try:
        cmd = open(p, 'rb').read().decode(errors='replace')
    except Exception:
        continue
    if 'pypi-server' in cmd or 'pypiserver' in cmd:
        pid = int(p.split('/')[2])
        if pid == os.getpid():
            continue
        print('killing', pid, cmd.replace('\x00', ' '))
        try:
            os.kill(pid, signal.SIGTERM)
        except Exception as e:
            print('err', e)
